<script setup>
import {ref,onMounted,computed} from 'vue';import AppShell from '../components/AppShell.vue';import {supabase} from '../services/supabase';const users=ref([]),jobs=ref([]),apps=ref([]),tab=ref('overview'),loading=ref(true),search=ref(''),error=ref('');const filtered=computed(()=>users.value.filter(u=>`${u.full_name} ${u.email}`.toLowerCase().includes(search.value.toLowerCase())));onMounted(async()=>{const [u,j,a]=await Promise.all([supabase.rpc('admin_list_users'),supabase.from('jobs').select('*, employer:profiles!jobs_employer_id_fkey(full_name,company_name)').order('created_at',{ascending:false}).limit(100),supabase.from('applications').select('id,status')]);users.value=u.data||[];jobs.value=j.data||[];apps.value=a.data||[];error.value=u.error?.message||j.error?.message||'';loading.value=false});async function status(u,value){const {error:e}=await supabase.from('profiles').update({status:value}).eq('id',u.id);if(e)error.value=e.message;else u.status=value}async function verify(u){const {error:e}=await supabase.from('profiles').update({verification_status:u.verification_status==='verified'?'unverified':'verified'}).eq('id',u.id);if(e)error.value=e.message;else u.verification_status=u.verification_status==='verified'?'unverified':'verified'}async function jobStatus(j,value){const {error:e}=await supabase.from('jobs').update({status:value}).eq('id',j.id);if(e)error.value=e.message;else j.status=value}
</script>
<template><AppShell title="Admin centre" subtitle="Platform oversight and moderation"><template #default><span class="eyebrow">CAMPUS GIG CONTROL ROOM</span><h1 class="page-title">Admin centre</h1><p class="page-subtitle">Monitor members, job posts and platform activity.</p><div v-if="error" class="alert error">{{error}} — Ensure the Campus Gig database schema has been installed.</div><div v-if="loading" class="empty">Loading platform data…</div><template v-else><div class="grid grid-3" style="margin-top:22px"><div class="stat"><strong>{{users.length}}</strong><span>Registered members</span></div><div class="stat"><strong>{{jobs.length}}</strong><span>Recent job posts</span></div><div class="stat"><strong>{{apps.length}}</strong><span>Applications</span></div></div><div class="tabs"><button :class="{active:tab==='overview'}" @click="tab='overview'">Overview</button><button :class="{active:tab==='users'}" @click="tab='users'">Members</button><button :class="{active:tab==='jobs'}" @click="tab='jobs'">Job posts</button></div><template v-if="tab==='overview'"><div class="card"><h3>Platform health</h3><p class="muted">Review new members and keep job posts accurate, safe and relevant to students.</p><div class="grid grid-2"><div><b>Active jobs</b><h2>{{jobs.filter(j=>j.status==='active').length}}</h2></div><div><b>Pending applications</b><h2>{{apps.filter(a=>a.status==='submitted'||a.status==='reviewing').length}}</h2></div></div></div></template><template v-else-if="tab==='users'"><input v-model="search" class="input" placeholder="Search members by name or email…"><div class="table-wrap" style="margin-top:15px"><table><thead><tr><th>Member</th><th>Type</th><th>Status</th><th>Verification</th><th>Joined</th><th>Action</th></tr></thead><tbody><tr v-for="u in filtered" :key="u.id"><td><b>{{u.full_name}}</b><div class="muted">{{u.email}}</div></td><td>{{u.account_type}}</td><td><span class="badge" :class="u.status==='active'?'green':'gold'">{{u.status}}</span></td><td><button v-if="u.account_type==='employer'" class="btn btn-outline small" @click="verify(u)">{{u.verification_status==='verified'?'Verified ✓':'Verify employer'}}</button><span v-else>—</span></td><td>{{new Date(u.created_at).toLocaleDateString('en-ZA')}}</td><td><button class="btn btn-outline small" @click="status(u,u.status==='active'?'suspended':'active')">{{u.status==='active'?'Suspend':'Reactivate'}}</button></td></tr></tbody></table></div></template><template v-else><div class="table-wrap"><table><thead><tr><th>Job</th><th>Employer</th><th>Type</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="j in jobs" :key="j.id"><td>{{j.title}}</td><td>{{j.employer?.company_name||j.employer?.full_name}}</td><td>{{j.job_type}}</td><td>{{j.status}}</td><td><button class="btn btn-outline small" @click="jobStatus(j,j.status==='active'?'paused':'active')">{{j.status==='active'?'Pause':'Activate'}}</button></td></tr></tbody></table></div></template></template></template></AppShell></template>
<style scoped>.tabs{display:flex;gap:8px;margin:22px 0 14px;border-bottom:1px solid var(--border)}.tabs button{border:0;background:none;color:var(--muted);padding:11px 15px;font-weight:700}.tabs button.active{color:var(--green);border-bottom:2px solid var(--green)}.small{padding:7px 10px;font-size:11px}</style>
